#include <bits/stdc++.h>

using namespace std;

using ll = long long;

const int MAXM = 103;
const ll MOD = 1000000007;

ll N;
int M;

inline ll mult(ll a, ll b) {
    return (a % MOD) * (b % MOD) % MOD;
}

inline ll add(ll a, ll b) {
    return (a % MOD + b % MOD) % MOD;
}

struct matrix {
    int n, m;
    ll mat[MAXM][MAXM];

    matrix(int n, int m) : n(n), m(m) {
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < m; ++j)
                mat[i][j] = 0;
    }

    matrix operator*(const matrix& b) const {
        matrix c(n, b.m);
        for (int i = 0; i < n; ++i) {
            for (int k = 0; k < m; ++k) {
                for (int j = 0; j < b.m; ++j) {
                    c.mat[i][j] = add(c.mat[i][j],
                                      mult(mat[i][k], b.mat[k][j]));
                }
            }
        }
        return c;
    }
};

matrix exponentiate(matrix base, ll exponent) {
    matrix result(M, M);
    for (int i = 0; i < M; ++i)
        result.mat[i][i] = 1;

    while (exponent > 0) {
        if (exponent & 1LL)
            result = result * base;
        exponent >>= 1LL;
        if (exponent > 0)
            base = base * base;
    }

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> M;

    matrix transition(M, M);
    transition.mat[0][0] = 1;
    transition.mat[0][M - 1] = 1;

    for (int i = 1; i < M; ++i)
        transition.mat[i][i - 1] = 1;

    matrix powered = exponentiate(transition, N);
    matrix start(M, 1);
    start.mat[0][0] = 1;

    cout << (powered * start).mat[0][0] << '\n';
    return 0;
}

