#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const ll MOD = 1000000007;

struct Matrix {
    int n, m;
    vector<ll> mat;

    Matrix(int n, int m) : n(n), m(m), mat(static_cast<size_t>(n) * m, 0) {}

    ll& operator()(int i, int j) {
        return mat[static_cast<size_t>(i) * m + j];
    }

    const ll& operator()(int i, int j) const {
        return mat[static_cast<size_t>(i) * m + j];
    }

    Matrix operator*(const Matrix& other) const {
        Matrix result(n, other.m);

        for (int i = 0; i < n; ++i) {
            for (int k = 0; k < m; ++k) {
                if ((*this)(i, k) == 0) continue;
                for (int j = 0; j < other.m; ++j) {
                    result(i, j) =
                        (result(i, j) + (*this)(i, k) * other(k, j)) % MOD;
                }
            }
        }

        return result;
    }
};

Matrix power(Matrix base, ll exponent) {
    Matrix result(base.n, base.n);
    for (int i = 0; i < base.n; ++i) {
        result(i, i) = 1;
    }

    while (exponent > 0) {
        if (exponent & 1LL) {
            result = result * base;
        }
        exponent >>= 1LL;
        if (exponent > 0) {
            base = base * base;
        }
    }

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll N;
    int M;
    cin >> N >> M;

    Matrix transition(M, M);
    transition(0, 0) = 1;
    transition(0, M - 1) = 1;

    for (int i = 1; i < M; ++i) {
        transition(i, i - 1) = 1;
    }

    Matrix powered = power(transition, N);
    cout << powered(0, 0) << '\n';

    return 0;
}

